  'suggestions.comprendre.1_creer_gamme_equipement': { one: '<b>S1 · Create a task list</b>: tracked equipment with no active task list, at least {n} breakdown with the same cause over the period.', other: '<b>S1 · Create a task list</b>: tracked equipment with no active task list, at least {n} breakdowns with the same cause over the period.' },
  'suggestions.comprendre.2_revoir_preventif_equipement': { one: '<b>S2 · Review the preventive maintenance</b>: equipment with a tracked task list that has already had a visit; at least {n} breakdown with the same cause over the period, after the first visit. To be examined: the task list does not say which breakdowns it prevents.', other: '<b>S2 · Review the preventive maintenance</b>: equipment with a tracked task list that has already had a visit; at least {n} breakdowns with the same cause over the period, after the first visit. To be examined: the task list does not say which breakdowns it prevents.' },
  'suggestions.comprendre.3_anomalies_repetees_gamme': '<b>S3 · Repeated faults</b>: tracked task list with a fault found at at least 2 of the last 4 visits.',
  'suggestions.comprendre.4_allonger_gamme_depuis_format_2': { one: '<b>S4 · Lengthen a task list</b>: tracked task list for equipment of criticality B or C (never A); at least {n} visit in a row with no fault found (counted since the switch to format 2, on {date}), and no breakdown of the equipment since the first of those visits. Statutory inspections are never suggested.', other: '<b>S4 · Lengthen a task list</b>: tracked task list for equipment of criticality B or C (never A); at least {n} visits in a row with no fault found (counted since the switch to format 2, on {date}), and no breakdown of the equipment since the first of those visits. Statutory inspections are never suggested.' },
  'suggestions.comprendre.4_allonger_gamme_gamme': { one: '<b>S4 · Lengthen a task list</b>: tracked task list for equipment of criticality B or C (never A); at least {n} visit in a row with no fault found, and no breakdown of the equipment since the first of those visits. Statutory inspections are never suggested.', other: '<b>S4 · Lengthen a task list</b>: tracked task list for equipment of criticality B or C (never A); at least {n} visits in a row with no fault found, and no breakdown of the equipment since the first of those visits. Statutory inspections are never suggested.' },
