  'suggestions.comprendre.date_ot_fin_travaux': '<b>Date of a work order</b>: end of the work, otherwise technical closure, otherwise creation.',
  'suggestions.comprendre.definitions': 'Definitions',
  'suggestions.comprendre.equipement_suivi_actif_pas': '<b>Tracked equipment</b>: active and not scrapped. <b>Tracked task list</b>: active, by date or by meter (never by threshold), for tracked equipment.',
  'suggestions.comprendre.intervalle_median_ecart_milieu': '<b>Median interval</b>: the middle gap, in days, between two consecutive breakdowns (half of the gaps are shorter).',
