  'indicateurs.comprendre.comprendre_indicateurs': 'Understanding these indicators',
  'indicateurs.comprendre.cout_main_uvre_pieces': '<b>Cost</b>: labour + parts (at current price) + subcontracting of the work orders closed in the period.',
  'indicateurs.comprendre.delai_prise_charge_temps': '<b>Response time</b>: time between the request (or the creation of the work order) and the start of the job; median by priority and share of work orders taken on within the target time.',
  'indicateurs.comprendre.disponibilite_mtbf_mtbf_mttr': '<b>Availability</b> = MTBF ÷ (MTBF + MTTR); 100% if there were no breakdowns.',
  'indicateurs.comprendre.dont_attente_pieces_moyenne': '<b>of which waiting for parts</b>: average hours spent “On hold” for a part, read from the change log, over measurable breakdowns whose whole status history is in the log.',
  'indicateurs.comprendre.duree_arret_somme_durees': '<b>Downtime</b>: sum of the downtimes entered on breakdowns.',
  'indicateurs.comprendre.mtbf_temps_moyen_entre': '<b>MTBF</b> (mean time between failures) = (required time − downtime) ÷ number of breakdowns.',
  'indicateurs.comprendre.mttr_temps_moyen_retablissement': '<b>MTTR</b> (mean time to repair) = downtime ÷ number of measurable breakdowns (closed, with a downtime); waiting times (parts, production) are included.',
  'indicateurs.comprendre.non_calculable_selection': 'Cannot be calculated for this selection',
  'indicateurs.comprendre.ot_retard_ot_ouverts': '<b>Overdue work orders</b>: open work orders whose planned date has passed, as of today.',
  'indicateurs.comprendre.panne_ot_correctif_immediat': '<b>Breakdown</b>: a corrective work order (immediate or deferred) that stopped production, not cancelled, counted on the date of the work request (otherwise on the creation of the work order).',
  'indicateurs.comprendre.part_preventif_heures_passees': '<b>Preventive share</b>: hours spent on preventive work orders ÷ hours spent on all work orders (times entered in the period).',
  'indicateurs.comprendre.respect_preventif_part_ot': '<b>Preventive compliance</b>: share of fixed-interval preventive work orders due in the period (planned date + {tolerance}% of the task list interval) closed no later than the due date.',
  'indicateurs.comprendre.temps_requis_heures_fonctionnement': '<b>Required time</b>: operating hours per day of the equipment × days of the period (since it entered service). Without operating hours per day, the equipment “cannot be calculated”: it is counted in neither the MTBF nor the availability (never an estimate).',
